INSERT INTO symptoms (symptom_name,description,specialties,related_symptoms,urgency_score,possible_diseases,additional_info) VALUES
('Chest pain','Pain, pressure, tightness, squeezing, burning, or discomfort felt in the chest.',ARRAY['Cardiology','Emergency Medicine','Pulmonology','Gastroenterology'],ARRAY['Shortness of breath','Sweating','Nausea','Dizziness','Palpitations'],95,ARRAY['Acute coronary syndrome','Myocardial infarction','Angina','Pulmonary embolism','Pericarditis','Gastroesophageal reflux disease','Costochondritis'],'Sudden or severe chest pain, particularly with shortness of breath, sweating, nausea, dizziness, or pain radiating to the arm, jaw, back, or shoulder requires urgent medical assessment.'),
('Shortness of breath','A sensation of difficulty breathing, inability to get enough air, or unusually laboured breathing.',ARRAY['Pulmonology','Cardiology','Emergency Medicine'],ARRAY['Cough','Chest pain','Wheezing','Rapid breathing','Dizziness'],95,ARRAY['Asthma','Pneumonia','Chronic obstructive pulmonary disease','Pulmonary embolism','Heart failure','Anaphylaxis','Pneumothorax'],'Severe or sudden breathing difficulty is an emergency, especially when associated with chest pain, cyanosis, confusion, fainting, or facial or throat swelling.'),
('Severe headache','Intense head pain that is unusually severe, sudden, persistent, or different from a persons usual headaches.',ARRAY['Neurology','Emergency Medicine'],ARRAY['Nausea','Vomiting','Neck stiffness','Visual disturbance','Dizziness'],90,ARRAY['Subarachnoid haemorrhage','Migraine','Meningitis','Intracranial haemorrhage','Temporal arteritis','Hypertensive emergency'],'A sudden extremely severe headache or headache associated with neurological deficits, confusion, seizure, fever, or stiff neck requires urgent assessment.'),
('Fever','An elevation in body temperature commonly associated with infection or inflammation.',ARRAY['General Medicine','Infectious Disease','Emergency Medicine','Paediatrics'],ARRAY['Chills','Sweating','Fatigue','Headache','Muscle aches'],55,ARRAY['Viral infection','Bacterial infection','Influenza','Pneumonia','Urinary tract infection','Malaria','Dengue fever'],'Urgency depends on temperature, duration, age, immune status, associated symptoms, and underlying disease.'),
('Cough','A reflexive expulsion of air from the respiratory tract that may be dry or productive.',ARRAY['Pulmonology','General Medicine','ENT'],ARRAY['Sputum','Shortness of breath','Wheezing','Sore throat','Chest pain'],40,ARRAY['Viral upper respiratory infection','Influenza','Asthma','Pneumonia','Bronchitis','Gastroesophageal reflux disease','Chronic obstructive pulmonary disease'],'Coughing blood, severe breathing difficulty, chest pain, or a persistent unexplained cough requires medical evaluation.'),
('Sore throat','Pain, irritation, or scratchiness in the throat, often worsened by swallowing.',ARRAY['ENT','General Medicine','Infectious Disease'],ARRAY['Fever','Cough','Difficulty swallowing','Swollen lymph nodes','Hoarseness'],35,ARRAY['Viral pharyngitis','Streptococcal pharyngitis','Tonsillitis','Influenza','Infectious mononucleosis','Gastroesophageal reflux disease'],'Difficulty breathing, inability to swallow saliva, severe swelling, or rapidly worsening symptoms require urgent assessment.'),
('Abdominal pain','Pain or discomfort occurring anywhere between the chest and pelvis.',ARRAY['Gastroenterology','General Surgery','Emergency Medicine','General Medicine'],ARRAY['Nausea','Vomiting','Diarrhoea','Constipation','Fever'],75,ARRAY['Gastroenteritis','Appendicitis','Cholecystitis','Pancreatitis','Peptic ulcer disease','Gastroesophageal reflux disease','Bowel obstruction'],'Sudden severe abdominal pain, rigid abdomen, persistent vomiting, gastrointestinal bleeding, or fainting can indicate an emergency.'),
('Nausea','A sensation of impending vomiting or discomfort in the upper abdomen.',ARRAY['Gastroenterology','General Medicine','Emergency Medicine'],ARRAY['Vomiting','Abdominal pain','Dizziness','Loss of appetite','Sweating'],45,ARRAY['Gastroenteritis','Migraine','Food poisoning','Pregnancy','Medication adverse effect','Gastroesophageal reflux disease','Myocardial infarction'],'Nausea accompanied by severe chest pain, severe abdominal pain, neurological symptoms, or persistent vomiting requires prompt assessment.'),
('Vomiting','Forceful expulsion of stomach contents through the mouth.',ARRAY['Gastroenterology','General Medicine','Emergency Medicine'],ARRAY['Nausea','Abdominal pain','Diarrhoea','Dehydration','Dizziness'],65,ARRAY['Gastroenteritis','Food poisoning','Migraine','Intestinal obstruction','Appendicitis','Pancreatitis','Pregnancy'],'Persistent vomiting can cause dehydration and electrolyte abnormalities. Blood or coffee-ground material in vomit is an emergency warning sign.'),
('Diarrhoea','Frequent passage of loose or watery stools.',ARRAY['Gastroenterology','General Medicine','Infectious Disease'],ARRAY['Abdominal cramps','Nausea','Vomiting','Fever','Dehydration'],55,ARRAY['Gastroenteritis','Food poisoning','Irritable bowel syndrome','Inflammatory bowel disease','Antibiotic-associated diarrhoea','Malabsorption'],'Severe dehydration, blood in stool, persistent vomiting, severe abdominal pain, or prolonged diarrhoea requires medical evaluation.'),
('Constipation','Infrequent bowel movements or difficulty passing hard stools.',ARRAY['Gastroenterology','General Medicine'],ARRAY['Abdominal pain','Bloating','Straining','Hard stools','Reduced bowel frequency'],30,ARRAY['Functional constipation','Irritable bowel syndrome','Medication adverse effect','Hypothyroidism','Bowel obstruction'],'Sudden constipation with severe abdominal pain, vomiting, marked distension, or inability to pass gas may indicate bowel obstruction.'),
('Dizziness','A sensation of lightheadedness, unsteadiness, faintness, or abnormal movement of oneself or the surroundings.',ARRAY['Neurology','ENT','Cardiology','Emergency Medicine'],ARRAY['Vertigo','Nausea','Weakness','Fainting','Balance problems'],65,ARRAY['Benign paroxysmal positional vertigo','Vestibular neuritis','Ménière disease','Dehydration','Anaemia','Hypotension','Cardiac arrhythmia'],'Sudden dizziness with weakness, difficulty speaking, visual changes, severe headache, or loss of coordination requires urgent assessment.'),
('Fainting','A temporary loss of consciousness caused by reduced blood flow to the brain, usually followed by spontaneous recovery.',ARRAY['Cardiology','Neurology','Emergency Medicine'],ARRAY['Dizziness','Palpitations','Weakness','Confusion','Sweating'],90,ARRAY['Vasovagal syncope','Cardiac arrhythmia','Orthostatic hypotension','Structural heart disease','Seizure','Hypoglycaemia'],'Fainting during exertion or when associated with chest pain, palpitations, injury, neurological symptoms, or a family history of sudden cardiac death requires urgent evaluation.'),
('Palpitations','An awareness of the heartbeat that may feel rapid, pounding, fluttering, or irregular.',ARRAY['Cardiology','Emergency Medicine','General Medicine'],ARRAY['Chest pain','Dizziness','Shortness of breath','Fainting','Anxiety'],75,ARRAY['Atrial fibrillation','Supraventricular tachycardia','Premature beats','Ventricular arrhythmia','Hyperthyroidism','Anaemia','Anxiety'],'Palpitations with chest pain, fainting, severe shortness of breath, or sustained rapid heartbeat require urgent medical assessment.'),
('Fatigue','Persistent physical or mental exhaustion or reduced energy that is not adequately relieved by rest.',ARRAY['General Medicine','Endocrinology','Psychiatry'],ARRAY['Weakness','Sleepiness','Poor concentration','Exercise intolerance','Dizziness'],35,ARRAY['Anaemia','Hypothyroidism','Sleep disorders','Depression','Diabetes mellitus','Chronic infection','Medication adverse effect'],'Persistent unexplained fatigue should be evaluated for medical, sleep-related, psychological, nutritional, and medication-related causes.'),
('Weakness','Reduced muscle strength or a subjective feeling of reduced physical power.',ARRAY['Neurology','General Medicine','Emergency Medicine'],ARRAY['Fatigue','Dizziness','Numbness','Difficulty walking','Fainting'],80,ARRAY['Stroke','Anaemia','Electrolyte disturbance','Hypoglycaemia','Neuropathy','Myasthenia gravis','Infection'],'Sudden weakness, particularly affecting one side of the body, may indicate stroke and requires immediate emergency assessment.'),
('Numbness','Reduced or absent sensation in part of the body, sometimes described as pins and needles.',ARRAY['Neurology','Orthopaedics','Emergency Medicine'],ARRAY['Tingling','Weakness','Pain','Balance problems','Muscle weakness'],75,ARRAY['Peripheral neuropathy','Stroke','Transient ischaemic attack','Nerve compression','Multiple sclerosis','Diabetic neuropathy','Vitamin B12 deficiency'],'Sudden one-sided numbness or numbness associated with weakness, facial drooping, speech difficulty, or severe headache requires emergency assessment.'),
('Tingling','An abnormal prickling, pins-and-needles, burning, or crawling sensation in the skin.',ARRAY['Neurology','General Medicine','Orthopaedics'],ARRAY['Numbness','Weakness','Burning sensation','Pain','Muscle cramps'],45,ARRAY['Peripheral neuropathy','Nerve compression','Diabetic neuropathy','Vitamin B12 deficiency','Anxiety','Electrolyte disturbance'],'Persistent or progressive tingling should be assessed, particularly when associated with weakness or loss of coordination.'),
('Back pain','Pain or discomfort affecting the back, ranging from mild muscular discomfort to severe spinal or nerve-related pain.',ARRAY['Orthopaedics','Neurology','Rheumatology','Emergency Medicine'],ARRAY['Muscle stiffness','Leg pain','Numbness','Tingling','Weakness'],65,ARRAY['Muscle strain','Lumbar disc herniation','Sciatica','Osteoarthritis','Spinal stenosis','Vertebral fracture','Kidney stone'],'Back pain with loss of bladder or bowel control, saddle numbness, progressive leg weakness, fever, or major trauma requires urgent assessment.'),
('Joint pain','Pain, tenderness, stiffness, or discomfort arising from one or more joints.',ARRAY['Rheumatology','Orthopaedics','General Medicine'],ARRAY['Joint stiffness','Swelling','Redness','Reduced mobility','Fever'],45,ARRAY['Osteoarthritis','Rheumatoid arthritis','Gout','Septic arthritis','Viral arthritis','Lupus'],'A hot, swollen, acutely painful joint with fever can indicate septic arthritis and requires urgent assessment.'),
('Muscle pain','Aching, soreness, cramping, or tenderness affecting one or more muscles.',ARRAY['General Medicine','Rheumatology','Neurology'],ARRAY['Weakness','Fatigue','Muscle cramps','Fever','Joint pain'],35,ARRAY['Viral infection','Muscle strain','Fibromyalgia','Electrolyte disturbance','Inflammatory myopathy','Medication adverse effect'],'Severe muscle pain with weakness, dark urine, or significant physical exertion may require urgent assessment for muscle injury or rhabdomyolysis.'),
('Skin rash','An area of abnormal skin appearance that may involve redness, bumps, patches, scaling, itching, or blisters.',ARRAY['Dermatology','Allergy and Immunology','Infectious Disease'],ARRAY['Itching','Fever','Swelling','Blisters','Skin redness'],55,ARRAY['Contact dermatitis','Atopic dermatitis','Urticaria','Viral exanthem','Drug eruption','Psoriasis','Fungal infection'],'A rapidly spreading rash with facial or throat swelling, breathing difficulty, blistering, mucosal involvement, or severe systemic illness requires urgent evaluation.'),
('Itching','An uncomfortable skin sensation that creates an urge to scratch.',ARRAY['Dermatology','Allergy and Immunology','General Medicine'],ARRAY['Skin rash','Dry skin','Redness','Swelling','Hives'],35,ARRAY['Atopic dermatitis','Contact dermatitis','Urticaria','Scabies','Fungal infection','Cholestatic liver disease','Chronic kidney disease'],'Generalised or persistent itching without an obvious skin cause can sometimes be associated with systemic disease and warrants evaluation.'),
('Swelling','An abnormal increase in tissue size caused by fluid accumulation, inflammation, injury, or another process.',ARRAY['General Medicine','Cardiology','Nephrology','Vascular Medicine'],ARRAY['Pain','Redness','Weight gain','Shortness of breath','Reduced urine output'],70,ARRAY['Heart failure','Kidney disease','Venous insufficiency','Deep vein thrombosis','Lymphoedema','Allergic reaction'],'Sudden facial or tongue swelling with breathing difficulty may indicate anaphylaxis. One-sided leg swelling with pain can indicate deep vein thrombosis.'),
('Wheezing','A high-pitched whistling sound produced by narrowed airways, usually most noticeable during breathing out.',ARRAY['Pulmonology','Emergency Medicine'],ARRAY['Shortness of breath','Cough','Chest tightness','Rapid breathing'],70,ARRAY['Asthma','Chronic obstructive pulmonary disease','Bronchitis','Pneumonia','Anaphylaxis','Foreign body aspiration'],'Severe wheezing with difficulty speaking, cyanosis, facial swelling, or rapidly worsening breathing requires emergency assessment.'),
('Sputum production','Production and expulsion of mucus from the lower respiratory tract during coughing.',ARRAY['Pulmonology','General Medicine'],ARRAY['Cough','Fever','Shortness of breath','Chest discomfort','Wheezing'],45,ARRAY['Acute bronchitis','Pneumonia','Chronic obstructive pulmonary disease','Bronchiectasis','Asthma'],'Blood-stained sputum or significant breathing difficulty requires prompt medical evaluation.'),
('Coughing blood','Expectoration of blood or blood-streaked mucus originating from the respiratory tract.',ARRAY['Pulmonology','Emergency Medicine','Cardiology'],ARRAY['Cough','Chest pain','Shortness of breath','Dizziness','Fever'],90,ARRAY['Pulmonary embolism','Pneumonia','Tuberculosis','Bronchiectasis','Lung cancer','Severe bronchitis'], 'Coughing up more than small streaks of blood, particularly with breathing difficulty or chest pain, is an emergency warning sign.'),
('Difficulty swallowing','A sensation that food or liquid is difficult to move from the mouth or throat into the oesophagus or stomach.',ARRAY['Gastroenterology','ENT','Neurology'],ARRAY['Sore throat','Choking','Weight loss','Regurgitation','Coughing'],70,ARRAY['Oesophageal stricture','Achalasia','Gastroesophageal reflux disease','Stroke','Neuromuscular disease','Oesophageal cancer'],'Sudden inability to swallow or difficulty swallowing with breathing difficulty or choking requires urgent assessment.'),
('Loss of appetite','Reduced desire to eat or decreased food intake compared with usual.',ARRAY['General Medicine','Gastroenterology','Oncology'],ARRAY['Weight loss','Nausea','Fatigue','Abdominal pain','Early satiety'],30,ARRAY['Gastroenteritis','Depression','Chronic infection','Cancer','Liver disease','Medication adverse effect'],'Persistent unexplained appetite loss, particularly with significant weight loss, should be medically evaluated.'),
('Unintentional weight loss','A reduction in body mass that occurs without deliberate dieting or increased physical activity.',ARRAY['General Medicine','Endocrinology','Gastroenterology','Oncology'],ARRAY['Loss of appetite','Fatigue','Night sweats','Diarrhoea','Weakness'],50,ARRAY['Hyperthyroidism','Diabetes mellitus','Malignancy','Chronic infection','Malabsorption','Depression'],'Persistent unexplained weight loss warrants medical evaluation, particularly when accompanied by fever, night sweats, bleeding, or persistent gastrointestinal symptoms.'),
('Excessive thirst','An unusually strong or persistent desire to drink fluids.',ARRAY['Endocrinology','Nephrology','General Medicine'],ARRAY['Frequent urination','Dry mouth','Fatigue','Blurred vision','Weight loss'],60,ARRAY['Diabetes mellitus','Diabetes insipidus','Dehydration','Hypercalcaemia','Kidney disease'],'Persistent excessive thirst with frequent urination and unexplained weight loss can occur with diabetes and should be evaluated.'),
('Frequent urination','Needing to urinate more often than usual, sometimes including increased nighttime urination.',ARRAY['Urology','Endocrinology','Nephrology','Gynaecology'],ARRAY['Excessive thirst','Painful urination','Urgency','Pelvic pain','Fatigue'],50,ARRAY['Urinary tract infection','Diabetes mellitus','Overactive bladder','Benign prostatic hyperplasia','Pregnancy','Diuretic medication'],'New frequent urination accompanied by fever, flank pain, blood in urine, or severe pain requires medical assessment.'),
('Painful urination','Pain, burning, or discomfort occurring during urination.',ARRAY['Urology','Gynaecology','General Medicine'],ARRAY['Frequent urination','Urinary urgency','Pelvic pain','Blood in urine','Fever'],60,ARRAY['Urinary tract infection','Urethritis','Kidney stone','Sexually transmitted infection','Prostatitis','Vaginitis'],'Painful urination with fever, flank pain, vomiting, or systemic illness may indicate a more serious urinary infection.'),
('Blood in urine','Visible or microscopic presence of blood in the urine.',ARRAY['Urology','Nephrology','General Medicine'],ARRAY['Painful urination','Flank pain','Frequent urination','Abdominal pain'],70,ARRAY['Urinary tract infection','Kidney stone','Kidney disease','Bladder cancer','Kidney cancer','Prostatitis'],'Visible blood in urine should be medically evaluated even when painless. Heavy bleeding or clots with difficulty urinating requires urgent assessment.'),
('Seizure','A sudden episode of abnormal electrical activity in the brain that may cause altered awareness, abnormal movements, sensory symptoms, or loss of consciousness.',ARRAY['Neurology','Emergency Medicine'],ARRAY['Loss of consciousness','Muscle jerking','Confusion','Tongue injury','Incontinence'],95,ARRAY['Epilepsy','Febrile seizure','Stroke','Brain tumour','Central nervous system infection','Hypoglycaemia','Electrolyte disturbance'],'A first seizure, prolonged seizure, repeated seizures without recovery, seizure with serious injury, or seizure associated with breathing difficulty requires emergency care.'),
('Confusion','An acute or persistent disturbance in thinking, awareness, orientation, attention, or ability to understand surroundings.',ARRAY['Neurology','Geriatric Medicine','Emergency Medicine','General Medicine'],ARRAY['Dizziness','Memory problems','Weakness','Fever','Altered consciousness'],90,ARRAY['Delirium','Stroke','Sepsis','Hypoglycaemia','Electrolyte disturbance','Medication adverse effect','Dementia'],'Sudden confusion can indicate a serious medical or neurological condition and requires prompt assessment, particularly when accompanied by fever, weakness, or reduced consciousness.'),
('Vision changes','A new alteration in vision such as blurred vision, double vision, partial visual loss, flashes, or sudden loss of sight.',ARRAY['Ophthalmology','Neurology','Emergency Medicine'],ARRAY['Headache','Dizziness','Eye pain','Weakness','Numbness'],85,ARRAY['Migraine with aura','Retinal detachment','Stroke','Transient ischaemic attack','Glaucoma','Optic neuritis','Diabetic retinopathy'],'Sudden loss of vision or sudden visual disturbance associated with neurological symptoms requires emergency assessment.'),
('Hearing loss','A reduction in the ability to hear sounds in one or both ears.',ARRAY['ENT','Audiology','Neurology'],ARRAY['Ear pain','Tinnitus','Dizziness','Ear fullness'],60,ARRAY['Cerumen impaction','Otitis media','Noise-induced hearing loss','Ménière disease','Sudden sensorineural hearing loss','Ototoxic medication'],'Sudden sensorineural hearing loss can require urgent specialist assessment because early treatment may affect recovery.'),
('Tinnitus','Perception of ringing, buzzing, humming, hissing, or other sounds without an external sound source.',ARRAY['ENT','Audiology','Neurology'],ARRAY['Hearing loss','Dizziness','Ear fullness','Headache'],45,ARRAY['Noise-induced hearing loss','Ménière disease','Earwax impaction','Ototoxic medication','Acoustic neuroma','Temporomandibular disorder'],'New unilateral tinnitus, tinnitus with sudden hearing loss, or tinnitus with neurological symptoms should be medically assessed.'),
('Nasal congestion','Blockage or stuffiness of the nasal passages caused by swelling, mucus, inflammation, or structural narrowing.',ARRAY['ENT','General Medicine','Allergy and Immunology'],ARRAY['Runny nose','Sneezing','Facial pressure','Cough','Sore throat'],20,ARRAY['Viral upper respiratory infection','Allergic rhinitis','Sinusitis','Nasal polyps','Deviated nasal septum'],'Persistent, unilateral, recurrent, or severe nasal obstruction may require ENT assessment.'),
('Runny nose','Excessive nasal discharge that may be watery, thick, clear, yellow, or green.',ARRAY['ENT','General Medicine','Allergy and Immunology'],ARRAY['Nasal congestion','Sneezing','Cough','Sore throat'],15,ARRAY['Viral upper respiratory infection','Allergic rhinitis','Sinusitis','Nonallergic rhinitis'],'Most cases are caused by viral infection or rhinitis, but persistent or recurrent symptoms may require evaluation.'),
('Eye pain','Pain, aching, burning, pressure, or discomfort affecting one or both eyes.',ARRAY['Ophthalmology','Emergency Medicine'],ARRAY['Vision changes','Redness','Photophobia','Headache','Tearing'],80,ARRAY['Corneal abrasion','Conjunctivitis','Glaucoma','Uveitis','Keratitis','Optic neuritis'],'Severe eye pain with sudden vision loss, marked redness, halos, severe headache, or nausea requires urgent ophthalmic assessment.');